{
  "spec": "This change extends the todo app to support optional due dates (YYYY-MM-DD) and task completion status. The `add` command accepts a `--due` flag, and the `list` command displays due dates alongside task text. New `done` and `overdue` commands allow users to mark tasks complete and filter for late tasks. The storage layer handles backward compatibility for files without due dates or done flags, ensuring old JSON files load correctly.",
  "stack": "Python, json, argparse, datetime, pytest",
  "tasks": [
    {
      "id": 1,
      "title": "Add due date and done status to Task model",
      "files": ["todo/model.py"],
      "test": "tests/test_todo.py: test_model_defaults checks that Task initializes with due_date=None and done=False"
    },
    {
      "id": 2,
      "title": "Implement backward-compatible JSON loading",
      "files": ["todo/storage.py"],
      "test": "tests/test_todo.py: test_old_file_loads checks that loading a JSON file without 'due_date' or 'done' keys results in valid Task objects with defaults"
    },
    {
      "id": 3,
      "title": "Implement JSON saving with new fields",
      "files": ["todo/storage.py"],
      "test": "tests/test_todo.py: test_add_and_list checks that saving a task with a due date results in valid JSON containing the date"
    },
    {
      "id": 4,
      "title": "Parse --due argument in add command",
      "files": ["todo/cli.py"],
      "test": "tests/test_todo.py: test_add_with_due checks that passing --due creates a task with the specified date"
    },
    {
      "id": 5,
      "title": "Display due date in list output",
      "files": ["todo/listing.py"],
      "test": "tests/test_todo.py: test_list_shows_due_date checks that render() includes the due date string after task text when present"
    },
    {
      "id": 6,
      "title": "Implement done command to mark task complete",
      "files": ["todo/cli.py", "todo/storage.py"],
      "test": "tests/test_todo.py: test_done_marks_task checks that running done ID sets the task's done flag to True in storage"
    },
    {
      "id": 7,
      "title": "Implement overdue command to list late tasks",
      "files": ["todo/cli.py", "todo/listing.py"],
      "test": "tests/test_todo.py: test_overdue_lists_late_tasks checks that overdue command returns only incomplete tasks with past due dates, sorted oldest first"
    }
  ]
}
